def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Step 1: Sort the list of base classes in ascending order
    classes.sort()
    # Step 2: Iterate through the sorted list and remove any duplicates
    for i in range(len(classes) - 1):
        if classes[i] == classes[i + 1]:
            classes.pop(i)
    # Step 3: Return the sorted and deduplicated list
    return classes

