def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    formatted_sql = sql
    formatted_params = {}

    # Check if the params is a mapping or a sequence
    if isinstance(params, Mapping):
        # If the params is a mapping, iterate over each key-value pair
        for key, value in params.items():
            # Check if the key is a string or an integer
            if isinstance(key, (str, int)):
                # If the key is a string, replace it with the corresponding out-style parameter
                formatted_sql = formatted_sql.replace(f"{key}", f"@{key}")
                # Add the key-value pair to the formatted params
                formatted_params[key] = value
            else:
                # If the key is not a string or an integer, raise a ValueError
                raise ValueError("Invalid key type in params")
    elif isinstance(params, Sequence):
        # If the params is a sequence, iterate over each element
        for i, value in enumerate(params):
            # Replace the corresponding in-style parameter with the out-style parameter
            formatted_sql = formatted_sql.replace(f"{i}", f"@{i}")
            # Add the value to the formatted params
            formatted_params[i] = value
    else:
        # If the params is not a mapping or a sequence, raise a ValueError
        raise ValueError("Invalid params type")

    # Return the formatted SQL query and the formatted params
    return formatted_sql, formatted_params

