def pretty(self, indent=0, debug=False):
    if debug:
        print("Pretty printing with indent level", indent)
    result = ""
    if self.is_leaf():
        result += " " * indent + str(self.value) + "\n"
    else:
        result += " " * indent + "(" + str(self.value) + "\n"
        for child in self.children:
            result += child.pretty(indent + 2, debug)
        result += " " * indent + ")\n"
    return result

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.is_and():
            if arg.left.is_equal(arg.right):
                new_args.append(arg.left)
            elif arg.right.is_equal(arg.left):
                new_args.append(arg.right)
            else:
                new_args.append(arg)
        elif arg.is_or():
            if arg.left.is_equal(arg.right):
                new_args.append(arg.left)
            elif arg.right.is_equal(arg.left):
                new_args.append(arg.right)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

