def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        return 0
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if not all(char in alphabet for char in string):
        raise ValueError("string must only contain characters from the alphabet")
    result = 0
    for char in string:
        result *= len(alphabet)
        result += alphabet.index(char)
    return result

