    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Invalid command: {}".format(command))
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Invalid argument: {}".format(arg))
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Invalid working directory: {}".format(cwd))
    if env is not None and not isinstance(env, dict):
        raise ValueError("Invalid environment: {}".format(env))
    if verbose:
        print("Running command: {}".format(" ".join(commands + args)))
    try:
        result = subprocess.run(commands + args, cwd=cwd, env=env, capture_output=True, text=True)
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            result = e.stdout
        else:
            result = e.stderr
    return result

