def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is missing")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid spec content") from e

    if "name" not in spec_data:
        raise IRValidatorException("Missing 'name' field in spec")

    if "version" not in spec_data:
        raise IRValidatorException("Missing 'version' field in spec")

    if "description" not in spec_data:
        raise IRValidatorException("Missing 'description' field in spec")

    if "inputs" not in spec_data:
        raise IRValidatorException("Missing 'inputs' field in spec")

    if "outputs" not in spec_data:
        raise IRValidatorException("Missing 'outputs' field in spec")

    if "functions" not in spec_data:
        raise IRValidatorException("Missing 'functions' field in spec")

    return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("YAML file path is required")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException("YAML file not found")
    except yaml.YAMLError:
        raise IRValidatorException("Invalid YAML file")

    if "name" not in data or "version" not in data:
        raise IRValidatorException("Mandatory data missing in YAML file")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Step 1: Get the spec from the self object
    spec = self.spec

    # Step 2: Get the default values from the spec
    default_values = spec.get_default_values()

    # Step 3: Get the other sources of default values
    other_sources = self.get_other_default_sources()

    # Step 4: Resolve the default values
    resolved_defaults = self.resolve_defaults(default_values, other_sources)

    # Step 5: Return the resolved default values
    return resolved_defaults

